<?php require_once '../config.php';require_admin();$pdo=db();if(isset($_GET['delete'])){if(!hash_equals($_SESSION['csrf']??'',$_GET['csrf']??''))exit('Invalid token');$s=$pdo->prepare("DELETE FROM products WHERE id=?");$s->execute([(int)$_GET['delete']]);flash('success','Product deleted.');header('Location: products.php');exit;}$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare("SELECT * FROM products WHERE id=?");$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}$cats=$pdo->query("SELECT * FROM categories ORDER BY type,name")->fetchAll();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)($_POST['id']??0);$name=trim($_POST['name']);$cat=(int)$_POST['category_id'];$desc=trim($_POST['description']??'');$price=(float)$_POST['price'];$stock=(int)$_POST['stock'];$image=trim($_POST['image']??'📦');if($id){$s=$pdo->prepare("UPDATE products SET category_id=?,name=?,description=?,price=?,stock=?,image=? WHERE id=?");$s->execute([$cat,$name,$desc,$price,$stock,$image,$id]);flash('success','Product updated.');}else{$s=$pdo->prepare("INSERT INTO products(category_id,name,description,price,stock,image) VALUES(?,?,?,?,?,?)");$s->execute([$cat,$name,$desc,$price,$stock,$image]);flash('success','Product added.');}header('Location: products.php');exit;}?><!doctype html><html><head><meta charset="utf-8"><title>Manage Products</title><link rel="stylesheet" href="../assets/style.css"></head><body class="adminbody"><header><div class="top"><a class="brand" href="../index.php"><span>📖</span><b>Kalpalatha<small>Admin</small></b></a><div class="links"><a href="index.php">Dashboard</a><a href="logout.php">Logout</a></div></div></header><main class="dash"><div class="tablecard"><h1><?= $edit?'Edit':'Add' ?> Product</h1><form method="post" class="formgrid"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=$edit['id']??0?>"><label>Product Name<input name="name" required value="<?=e($edit['name']??'')?>"></label><label>Category<select name="category_id"><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=$edit&&$edit['category_id']==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></label><label>Price<input type="number" step="0.01" name="price" required value="<?=e((string)($edit['price']??''))?>"></label><label>Stock<input type="number" name="stock" required value="<?=e((string)($edit['stock']??0))?>"></label><label>Icon / Image text<input name="image" value="<?=e($edit['image']??'📦')?>"></label><label class="wide">Description<textarea name="description" rows="4"><?=e($edit['description']??'')?></textarea></label><div><button class="btn">Save Product</button> <a class="btn dark" href="products.php">Cancel</a></div></form></div></main></body></html>